<script lang="ts">
	import { enhance } from '$app/forms';
	import { read_contact, validate_contact, type ContactErrors } from '#lib/contact.js';
	import type { PageProps } from './$types';

	let { form }: PageProps = $props();

	/** Errors found in the browser, which take precedence over the server's until the next submission */
	let client_errors = $state<ContactErrors | null>(null);

	let errors = $derived<ContactErrors>(
		client_errors ?? (form && 'errors' in form ? form.errors : {})
	);
	let values = $derived(form && 'values' in form ? form.values : undefined);
	let success_name = $derived(form && 'success' in form ? form.name : undefined);
</script>

<svelte:head>
	<title>Contact | Bookshelf</title>
</svelte:head>

<h1>Contact</h1>

{#if success_name !== undefined}
	<p class="success" role="status">Thanks, {success_name}! Your message has been sent.</p>
{/if}

<form
	method="POST"
	novalidate
	use:enhance={({ formData, cancel }) => {
		const found = validate_contact(read_contact(formData));

		if (Object.keys(found).length > 0) {
			client_errors = found;
			cancel();
			return;
		}

		client_errors = null;
	}}
>
	<div class="field">
		<label for="name">Name</label>
		<input
			id="name"
			name="name"
			type="text"
